import{_ as E,I as n,c as i,o as t,a5 as a,b as o,w as l,a as s,J as A,a6 as d}from"./chunks/framework.BmNIwhaK.js";const b=JSON.parse('{"title":"[特許ホワイトペーパー] モバイルジェスチャー解析および自然言語テスト自動化システム","description":"モバイルタッチジェスチャーを無次元正規化ベクトルとして解析し、自然言語テストケースへ変換して異種デバイス上で適応実行する技術ホワイトペーパー","frontmatter":{"title":"[特許ホワイトペーパー] モバイルジェスチャー解析および自然言語テスト自動化システム","shortTitle":"[第21号] モバイルジェスチャー & 自然言語QA","category":"コア技術 & 特許","sort":4,"description":"モバイルタッチジェスチャーを無次元正規化ベクトルとして解析し、自然言語テストケースへ変換して異種デバイス上で適応実行する技術ホワイトペーパー","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/patents/21-mobile-gesture-nlp"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/patents/21-mobile-gesture-nlp"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/patents/21-mobile-gesture-nlp"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/patents/21-mobile-gesture-nlp"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/patents/21-mobile-gesture-nlp"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"[特許ホワイトペーパー] モバイルジェスチャー解析および自然言語テスト自動化システム | Empasy Docs"}],["meta",{"property":"og:description","content":"モバイルタッチジェスチャーを無次元正規化ベクトルとして解析し、自然言語テストケースへ変換して異種デバイス上で適応実行する技術ホワイトペーパー"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/patents/21-mobile-gesture-nlp"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"[特許ホワイトペーパー] モバイルジェスチャー解析および自然言語テスト自動化システム | Empasy Docs"}],["meta",{"name":"twitter:description","content":"モバイルタッチジェスチャーを無次元正規化ベクトルとして解析し、自然言語テストケースへ変換して異種デバイス上で適応実行する技術ホワイトペーパー"}]]},"headers":[],"relativePath":"ja/patents/21-mobile-gesture-nlp.md","filePath":"ja/patents/21-mobile-gesture-nlp.md","lastUpdated":1795293539000}'),c={name:"ja/patents/21-mobile-gesture-nlp.md"};function g(m,e,h,B,p,y){const r=n("Mermaid");return t(),i("div",null,[e[1]||(e[1]=a('<h1 id="モバイルジェスチャー解析および自然言語テスト自動化システム" tabindex="-1">モバイルジェスチャー解析および自然言語テスト自動化システム <a class="header-anchor" href="#モバイルジェスチャー解析および自然言語テスト自動化システム" aria-label="Permalink to “モバイルジェスチャー解析および自然言語テスト自動化システム”">​</a></h1><blockquote><p><strong>特許出願管理番号</strong>: 第21号<br><strong>発明の名称</strong>: モバイル端末ジェスチャーレコーディングおよびネイティブビュー階層解析を通じたAIベース自然言語テストケース生成および異種モバイルデバイス自動実行システム・その方法<br><strong>出願管理状態</strong>: 出願準備（早期審査対象、登録可能性Aランク評価）<br><strong>連携プロダクト</strong>: <code>SyncETA</code>, <code>SyncVerse</code></p></blockquote><hr><h2 id="_1-解決しようとする技術的課題" tabindex="-1">1. 解決しようとする技術的課題 <a class="header-anchor" href="#_1-解決しようとする技術的課題" aria-label="Permalink to “1. 解決しようとする技術的課題”">​</a></h2><p>モバイルアプリケーションの品質検証（QA）は、端末ごとの画面サイズ、解像度（DPI）、オペレーティングシステム（Android/iOS）の著しい断片化により、多大なコストを要します。</p><p>従来のモバイルテスト自動化ツール（例: Appium、Espresso、XCUITest）には、以下のような構造的限界がありました。</p><ol><li><strong>解像度およびレイアウト依存性</strong>: 絶対ピクセル座標ベースで記録されたジェスチャーは、アスペクト比が異なる端末では誤った位置をタッチして誤動作を引き起こします。</li><li><strong>識別子変更に伴うスクリプト破損</strong>: アプリのリファクタリングやビルドツールの変更によって <code>resource-id</code> や <code>accessibility-id</code> が変更されると、既存のテストスクリプトが全面的に無効化されます。</li><li><strong>高いエンジニアリング参入障壁</strong>: 複雑なプログラミングコードでテストスクリプトを記述する必要があるため、非エンジニアのQA担当者による活用が制限されていました。</li></ol>',7)),(t(),o(d,null,{default:l(()=>[A(r,{id:"mermaid-35",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20Device%5B%22%E3%83%A2%E3%83%90%E3%82%A4%E3%83%AB%E7%AB%AF%E6%9C%AB%E3%81%AE%E3%82%B8%E3%82%A7%E3%82%B9%E3%83%81%E3%83%A3%E3%83%BC%E5%85%A5%E5%8A%9B%20(%E3%82%BF%E3%83%83%E3%83%97%E3%80%81%E3%82%B9%E3%83%AF%E3%82%A4%E3%83%97%E7%AD%89)%22%5D%20--%3E%20Rec%5B%220.0%E3%80%9C1.0%20%E7%84%A1%E6%AC%A1%E5%85%83%E6%AD%A3%E8%A6%8F%E5%8C%96%E5%BA%A7%E6%A8%99%E7%B3%BB%E3%81%B8%E3%81%AE%E5%A4%89%E6%8F%9B%22%5D%0A%20%20%20%20Device%20--%3E%20Tree%5B%22%E3%82%A2%E3%82%AF%E3%82%BB%E3%82%B7%E3%83%93%E3%83%AA%E3%83%86%E3%82%A3%E3%83%8E%E3%83%BC%E3%83%89%E9%9A%8E%E5%B1%A4%20(Accessibility%20Tree)%20%E3%81%AE%E5%8F%8E%E9%9B%86%22%5D%0A%20%20%20%20Device%20--%3E%20Snap%5B%22%E8%A6%96%E8%A6%9A%E3%82%A2%E3%83%B3%E3%82%AB%E3%83%BC%20(Visual%20Anchor)%20%E3%82%B9%E3%82%AF%E3%83%AA%E3%83%BC%E3%83%B3%E3%82%B7%E3%83%A7%E3%83%83%E3%83%88%E3%81%AE%E3%82%AD%E3%83%A3%E3%83%97%E3%83%81%E3%83%A3%22%5D%0A%20%20%20%20Rec%20%26%20Tree%20%26%20Snap%20--%3E%20LLM%5B%22LLM%E3%83%99%E3%83%BC%E3%82%B9%E3%81%AE%E3%83%89%E3%83%A1%E3%82%A4%E3%83%B3%E3%82%AA%E3%83%B3%E3%83%88%E3%83%AD%E3%82%B8%E3%83%BC%E8%A7%A3%E6%9E%90%22%5D%0A%20%20%20%20LLM%20--%3E%20NL_TC%5B%22%E5%AE%9A%E5%9E%8B%E5%8C%96%E3%81%95%E3%82%8C%E3%81%9F%E8%87%AA%E7%84%B6%E8%A8%80%E8%AA%9E%E3%83%86%E3%82%B9%E3%83%88%E3%82%B1%E3%83%BC%E3%82%B9%E3%81%AE%E7%94%9F%E6%88%90%22%5D%0A%20%20%20%20NL_TC%20--%3E%20MCP%5B%22MCP%E3%83%99%E3%83%BC%E3%82%B9%E3%81%AE%E7%95%B0%E7%A8%AE%E3%83%87%E3%83%90%E3%82%A4%E3%82%B9%E3%83%95%E3%82%A1%E3%83%BC%E3%83%A0%E4%B8%A6%E5%88%97%E5%AE%9F%E8%A1%8C%22%5D%0A%20%20%20%20MCP%20--%3E%20Exec%7B%22UI%E8%AD%98%E5%88%A5%E5%AD%90%E3%81%AE%E6%9C%89%E5%8A%B9%E6%80%A7%E6%A4%9C%E8%A8%BC%22%7D%0A%20%20%20%20Exec%20--%20%22%E6%AD%A3%E5%B8%B8%E4%B8%80%E8%87%B4%22%20--%3E%20Done%5B%22%E3%83%86%E3%82%B9%E3%83%88%E5%AE%8C%E4%BA%86%E3%81%8A%E3%82%88%E3%81%B3%E3%83%AC%E3%83%9D%E3%83%BC%E3%83%88%22%5D%0A%20%20%20%20Exec%20--%20%22ID%E4%B8%8D%E4%B8%80%E8%87%B4%2F%E5%A4%89%E6%9B%B4%E6%A4%9C%E7%9F%A5%22%20--%3E%20VLM%5B%22VLM%E3%83%87%E3%83%A5%E3%82%A2%E3%83%AB%E3%83%91%E3%83%BC%E3%82%BB%E3%83%97%E3%82%B7%E3%83%A7%E3%83%B3%E8%9E%8D%E5%90%88%E3%82%B0%E3%83%A9%E3%82%A6%E3%83%B3%E3%83%87%E3%82%A3%E3%83%B3%E3%82%B0%20(%E8%87%AA%E5%B7%B1%E4%BF%AE%E5%BE%A9)%22%5D%0A%20%20%20%20VLM%20--%3E%20MCP%0A"})]),fallback:l(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=a('<hr><h2 id="_2-コア動作メカニズム" tabindex="-1">2. コア動作メカニズム <a class="header-anchor" href="#_2-コア動作メカニズム" aria-label="Permalink to “2. コア動作メカニズム”">​</a></h2><p>本発明は、ユーザーによる実際のモバイル端末操作をキャプチャして自然言語仕様書に変換し、それを異種デバイス上で自律適応型に再生する全工程を包含します。</p><h3 id="ステップ1-ジェスチャーベクトルの正規化およびマルチコンテキスト収集" tabindex="-1">ステップ1: ジェスチャーベクトルの正規化およびマルチコンテキスト収集 <a class="header-anchor" href="#ステップ1-ジェスチャーベクトルの正規化およびマルチコンテキスト収集" aria-label="Permalink to “ステップ1: ジェスチャーベクトルの正規化およびマルチコンテキスト収集”">​</a></h3><ul><li>ユーザーが実機画面をタッチ（タップ、ロングプレス、スワイプ、ドラッグなど）する際に発生する入力イベントの時系列軌跡、接触面積、圧力値を収集します。</li><li>特定端末のピクセル解像度に依存しないよう、X・Y座標を <strong>0.0から1.0の間の無次元正規化相対座標系ベクトル</strong> に変換します。</li><li>タッチ発生時点の画面画像から特徴ベクトルとバウンディングボックスを抽出した <strong>視覚アンカー（Visual Anchor）</strong> を生成し、OSのネイティブアクセシビリティノード階層（Accessibility Node Hierarchy）を統合します。</li></ul><h3 id="ステップ2-llmオントロジーに基づく自然言語テストケースの自動生成" tabindex="-1">ステップ2: LLMオントロジーに基づく自然言語テストケースの自動生成 <a class="header-anchor" href="#ステップ2-llmオントロジーに基づく自然言語テストケースの自動生成" aria-label="Permalink to “ステップ2: LLMオントロジーに基づく自然言語テストケースの自動生成”">​</a></h3><ul><li>収集された複合データ（正規化座標、ノード階層テキスト、視覚的コンポーネント情報）を大規模言語モデルへ渡します。</li><li>モデルはモバイルインタラクションドメインのオントロジー規則を参照し、開発者以外の一般ユーザーでも即座に理解できる定型化されたテストステップ（操作、入力値、期待結果）として自動記述します。 <ul><li><em>例</em>: <em>「ログイン画面でID入力欄に &#39;testuser&#39; を入力し、パスワードを入力した後、&#39;ログイン&#39; ボタンをタップしてメインダッシュボードへ遷移することを確認する。」</em></li></ul></li></ul><h3 id="ステップ3-mcp標準プロトコルに基づく異種デバイスファームでの適応実行" tabindex="-1">ステップ3: MCP標準プロトコルに基づく異種デバイスファームでの適応実行 <a class="header-anchor" href="#ステップ3-mcp標準プロトコルに基づく異種デバイスファームでの適応実行" aria-label="Permalink to “ステップ3: MCP標準プロトコルに基づく異種デバイスファームでの適応実行”">​</a></h3><ul><li>生成された自然言語テストケースは、Model Context Protocol（MCP）ツールインターフェースを通じて、遠隔に分散配置された多数の実機（Android、iOS、タブレットなど）へブロードキャストされます。</li><li>各端末の解像度、ノッチ（Notch）および下部ホームバー（Safe Area）の余白に合わせて正規化座標が対象端末の物理ピクセルへとリアルタイムにマッピングされ、正確な位置を操作します。</li></ul><h3 id="ステップ4-vlmデュアルパーセプション融合に基づく自己修復-self-healing" tabindex="-1">ステップ4: VLMデュアルパーセプション融合に基づく自己修復（Self-Healing） <a class="header-anchor" href="#ステップ4-vlmデュアルパーセプション融合に基づく自己修復-self-healing" aria-label="Permalink to “ステップ4: VLMデュアルパーセプション融合に基づく自己修復（Self-Healing）”">​</a></h3><ul><li>アプリのバージョンアップによりネイティブUI識別子（ID）が変更された場合、Vision-Language Model（VLM）が視覚アンカー画像と変更後の画面との間でデュアルパーセプション融合グラウンディング（IoU 0.10〜0.30閾値）を実行します。</li><li>形状やテキスト位置が類似した代替コンポーネントをインテリジェントに探索して途切れることなくテストを継続し、修復されたセレクタ情報を結果レポートに記録します。</li></ul><hr><h2 id="_3-先行技術との比較・優位性" tabindex="-1">3. 先行技術との比較・優位性 <a class="header-anchor" href="#_3-先行技術との比較・優位性" aria-label="Permalink to “3. 先行技術との比較・優位性”">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">比較項目</th><th style="text-align:left;">従来のスクリプトツール（Appium等）</th><th style="text-align:left;">座標マクロレコーダー</th><th style="text-align:left;">本特許システム（21号）</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>テストケース形式</strong></td><td style="text-align:left;">プログラミング言語コード（Java、Python）</td><td style="text-align:left;">単純なピクセル座標の羅列</td><td style="text-align:left;"><strong>人間が読める自然言語仕様書</strong></td></tr><tr><td style="text-align:left;"><strong>異機種デバイス互換性</strong></td><td style="text-align:left;">端末ごとのスクリプト分岐処理が必要</td><td style="text-align:left;">解像度変更時に誤動作</td><td style="text-align:left;"><strong>無次元正規化相対座標系への変換</strong></td></tr><tr><td style="text-align:left;"><strong>UI識別子変更時</strong></td><td style="text-align:left;">テストが即座に中断・失敗処理</td><td style="text-align:left;">復旧不可</td><td style="text-align:left;"><strong>VLMデュアルパーセプションに基づく自己修復</strong></td></tr><tr><td style="text-align:left;"><strong>テスト管理のアクセシビリティ</strong></td><td style="text-align:left;">専門のテストエンジニアが必須</td><td style="text-align:left;">保守が不可能</td><td style="text-align:left;"><strong>一般QAおよび企画担当者も即座に活用可能</strong></td></tr></tbody></table><hr><h2 id="_4-実測性能およびコードベース実装証跡" tabindex="-1">4. 実測性能およびコードベース実装証跡 <a class="header-anchor" href="#_4-実測性能およびコードベース実装証跡" aria-label="Permalink to “4. 実測性能およびコードベース実装証跡”">​</a></h2><p>国内外の主要Android/iOS代表端末12機種（スマートフォン8機種、タブレット4機種）を対象とした500回の回帰テスト実測結果は以下のとおりです。</p><ul><li><strong>クロスデバイス再生精度</strong>: 単一端末でのレコーディング後、異種解像度端末11機種での再生成功率 <strong>98.2%</strong> を記録。</li><li><strong>UI変更自己修復率</strong>: ネイティブID変更およびレイアウト変形の状況下において、VLM融合グラウンディングによる自律復旧率 <strong>93.5%</strong> を達成。</li><li><strong>テストケース作成時間</strong>: 従来のコードスクリプト作成と比較して、自然言語変換により作成所要時間を <strong>約78%短縮</strong>。</li></ul><h3 id="コードベース実装箇所-grounding" tabindex="-1">コードベース実装箇所（Grounding） <a class="header-anchor" href="#コードベース実装箇所-grounding" aria-label="Permalink to “コードベース実装箇所（Grounding）”">​</a></h3><ul><li><code>SyncETA/Server/src/main/java/com/empasy/sync/eta/service/MobileAgentService.java</code>: モバイルエージェント制御器</li><li><code>SyncETA/Server/src/main/java/com/empasy/sync/eta/service/MobileTcParserService.java</code>: 自然言語テストケースパーサーおよび生成器</li><li><code>SyncETA/Server/src/main/java/com/empasy/sync/eta/service/RemoteAdbService.java</code>: リモートAndroid ADBパイプライン</li><li><code>SyncETA/Server/src/main/java/com/empasy/sync/eta/service/RemoteIosService.java</code>: リモートiOS WebDriverAgent連携器</li></ul>',20))])}const u=E(c,[["render",g]]);export{b as __pageData,u as default};
